<template>
  <Dialog v-model:open="model" @update:open="onOpenUpdate">
    <DialogTrigger as-child>
      <slot>
        <Button size="sm" variant="outline" :prepend-icon="RotateCcwIcon">Reset Counters</Button>
      </slot>
    </DialogTrigger>
    <DialogContent :class="cn('rounded-lg gap-6', mode === 'batch' ? 'max-w-md' : 'max-w-sm')">
      <DialogHeader class="gap-y-2 text-left">
        <DialogTitle class="text-xl">Reset Counters?</DialogTitle>
        <DialogDescription class="font-normal text-base text-accent-foreground">
          {{
            mode === 'batch'
              ? `You are about to reset counters for ${contacts.length} contact(s). Select which counters to reset.`
              : 'Select which counters to reset.'
          }}
        </DialogDescription>
      </DialogHeader>

      <div v-if="mode === 'batch'" class="max-h-60 overflow-y-auto border rounded-md divide-y">
        <div v-for="contact in contacts" :key="contact.email" class="flex flex-col px-3 py-2">
          <span class="text-sm font-medium">
            {{ formatContactName(contact.first_name, contact.last_name) }}
          </span>
          <span class="text-xs text-muted-foreground">{{ contact.email }}</span>
        </div>
      </div>

      <div class="flex flex-col gap-3">
        <label class="flex items-center gap-2 cursor-pointer">
          <Checkbox v-model="resetGeneral" />
          <span class="text-sm">Reset General Counter</span>
        </label>
        <label class="flex items-center gap-2 cursor-pointer">
          <Checkbox v-model="resetProject" />
          <span class="text-sm">Reset Project Counter</span>
        </label>
      </div>

      <DialogFooter>
        <div class="flex flex-wrap justify-end gap-2">
          <DialogClose as-child>
            <Button variant="outline" class="h-10 px-4">Cancel</Button>
          </DialogClose>
          <Button
            variant="destructive"
            class="h-10 px-4"
            :loading="isLoading"
            :disabled="isLoading || (!resetGeneral && !resetProject)"
            @click="onConfirm"
          >
            Reset
          </Button>
        </div>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { RotateCcwIcon } from 'lucide-vue-next';
import { cn } from '@/lib/utils';
import { useResetCounters } from '~/mutations/staffing-contacts/resetCounters';
import { useResetCountersBatch } from '~/mutations/staffing-contacts/resetCountersBatch';
import { DialogContent, DialogTrigger } from '~/components/ui/dialog';
import { Checkbox } from '~/components/ui/checkbox';

interface ResetCountersContact {
  email: string;
  first_name: string | null;
  last_name: string | null;
}

const props = defineProps<{
  mode: 'single' | 'batch';
  contacts: ResetCountersContact[];
}>();

const emit = defineEmits<{ (e: 'reset'): void }>();

const model = defineModel<boolean>({ default: false });

const resetGeneral = ref(false);
const resetProject = ref(false);

// also called at the programmatic close in onConfirm - reka doesn't emit update:open for controlled writes
function onOpenUpdate(open: boolean) {
  if (!open) {
    resetGeneral.value = false;
    resetProject.value = false;
  }
}

const { resetCounters, isResetCountersLoading } = useResetCounters();
const { resetCountersBatch, isResetCountersBatchLoading } = useResetCountersBatch();

const isLoading = computed(() => isResetCountersLoading.value || isResetCountersBatchLoading.value);

async function onConfirm() {
  try {
    if (props.mode === 'batch') {
      await resetCountersBatch({
        emails: props.contacts.map((c) => c.email),
        general: resetGeneral.value,
        project: resetProject.value,
      });
    } else {
      await resetCounters({
        email: props.contacts[0].email,
        data: { general: resetGeneral.value, project: resetProject.value },
      });
    }
    model.value = false;
    onOpenUpdate(false);
    emit('reset');
  } catch {
    // mutation toasted; keep open for retry
  }
}
</script>
