import { batchResetStaffingContactCounters } from '~/client';
import type { BatchResetStaffingContactCountersResponse, ResetCountersBatchRequest } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useResetCountersBatch = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: ResetCountersBatchRequest): Promise<BatchResetStaffingContactCountersResponse> =>
      batchResetStaffingContactCounters({ composable: '$fetch', body: ref(data) }),
    onSuccess: (_, vars) => {
      queryCache.invalidateQueries({ key: ['staffing-contacts.list'] });
      const count = vars.emails.length;
      showToastSuccess(`Counters reset for ${count} contact${count === 1 ? '' : 's'}`);
    },
    onError: (error) => {
      showToastError(error);
    },
  });
  return {
    resetCountersBatch: mutateAsync,
    isResetCountersBatchLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
