import {
  sendBatchRecruitmentMessages,
  type RecruitmentChannelStrategy,
  type RecruitmentMessageSendBatchResponse,
} from '~/client';

export const useRecruitmentMessageSendBatch = defineMutation(() => {
  const { mutateAsync: sendBatch, asyncStatus } = useMutation({
    mutation: (vars: {
      emails: string[];
      idempotency_key: string;
      ignore_quiet_hours?: boolean;
      channel_strategy?: RecruitmentChannelStrategy | null;
    }): Promise<RecruitmentMessageSendBatchResponse> =>
      sendBatchRecruitmentMessages({
        composable: '$fetch',
        body: {
          emails: vars.emails,
          idempotency_key: vars.idempotency_key,
          ignore_quiet_hours: vars.ignore_quiet_hours,
          // null = "use the context's configured strategy" -> omit so the optional body field is absent.
          channel_strategy: vars.channel_strategy ?? undefined,
        },
      }),
    onError(error) {
      showToastError(error);
    },
  });

  return {
    sendBatch,
    isSendBatchLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
