import type { SkippedContactReason } from '~/client';

interface SkippedReasonEntry {
  label: string;
}

export const skippedContactReasonConfig: Record<SkippedContactReason, SkippedReasonEntry> = {
  not_found: { label: 'Not Found' },
  stopped: { label: 'Stopped' },
  unsubscribed: { label: 'Unsubscribed' },
  spam_complaint: { label: 'Spam Complaint' },
  hard_bounced: { label: 'Hard Bounced' },
  do_not_hire: { label: 'Do Not Hire' },
  already_applied: { label: 'Already Applied' },
  user_inactive: { label: 'User Inactive' },
  user_is_staff: { label: 'Staff Member' },
  already_fully_onboarded: { label: 'Already Fully Onboarded' },
  contact_busy: { label: 'Contact Busy' },
  sms_opted_out: { label: 'SMS Opted Out' },
  not_textable: { label: 'Not Textable' },
  sms_lookup_unavailable: { label: 'SMS Lookup Unavailable' },
  unreachable: { label: 'Unreachable' },
  // shown when a send is retried: the contact got no message when this batch first ran, and the original
  // skip reason is no longer available. Renders after a "Skipped - " prefix.
  skipped_on_previous_attempt: { label: 'Not in the Original Send' },
};

export function getSkippedContactReason(reason: SkippedContactReason): SkippedReasonEntry {
  return skippedContactReasonConfig[reason] ?? { label: snakeCaseToCapitalizedCase(reason) };
}
