import { resetStaffingContactCounters } from '~/client';
import type { ResetStaffingContactCountersResponse, ResetCountersRequest } from '~/client';

export const useResetCounters = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: { email: string; data: ResetCountersRequest }): Promise<ResetStaffingContactCountersResponse> =>
      resetStaffingContactCounters({
        composable: '$fetch',
        path: { email: params.email },
        body: params.data,
      }),
    onSuccess: (_, params) => {
      queryCache.invalidateQueries({ key: ['staffing-contact', params.email] });
      queryCache.invalidateQueries({ key: ['staffing-contacts.list'] });
      showToastSuccess('Counters reset successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    resetCounters: mutateAsync,
    isResetCountersLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
