import { showToastError, showToastInfo, showToastSuccess } from '~/utils/show-toast';

interface SendBatchResult {
  createdCount: number;
  skippedCount: number;
}

interface SendBatchToastMessages {
  allSent: { title: string; description?: string };
  partial: { title: string; description?: string };
  allSkipped: { title: string; description?: string };
}

/**
 * all-skipped is an error toast, never success. Returns allSkipped so the caller
 * can drive follow-up (open skip list, close dialog, etc.).
 */
export function showSendBatchResultToast(
  { createdCount, skippedCount }: SendBatchResult,
  messages: SendBatchToastMessages
): { allSkipped: boolean } {
  const allSkipped = createdCount === 0;

  if (allSkipped) {
    // showToastError takes (body, title)
    showToastError(messages.allSkipped.description, messages.allSkipped.title);
  } else if (skippedCount > 0) {
    showToastInfo(messages.partial.title, messages.partial.description);
  } else {
    showToastSuccess(messages.allSent.title, messages.allSent.description);
  }

  return { allSkipped };
}
